### **4. BaseEsiClient Pattern: `src/clients/BaseEsiClient.ts`**

**Key insight (file path: `/d/code/ESI.ts/src/clients/BaseEsiClient.ts`):**

```typescript
export abstract class BaseEsiClient<T extends EndpointMap> {
  protected api: ClientMethods<T>;
  protected _client: ApiClient;
  private _endpoints: T;
  private _metaApi?: ClientMethods<T>;

  constructor(client: ApiClient, endpoints: T) {
    this._client = client;
    this._endpoints = endpoints;
    this.api = createClient(client, endpoints);  // <-- Dynamic method generation
  }

  withMetadata(): WithMetadata<Omit<this, 'withMetadata'>> {
    if (!this._metaApi) {
      this._metaApi = createClient(this._client, this._endpoints, {
        returnMetadata: true,
      } as CreateClientOptions);
    }
    return this._metaApi as unknown as WithMetadata<Omit<this, 'withMetadata'>>;
  }
}
```

**How it works:**
- `createClient()` generates all method implementations dynamically from endpoint definitions
- Each endpoint in the map becomes a method that builds the request and calls the ApiClient
- The SovereigntyClient wraps these auto-generated methods with type annotations and documentation

